    public class DefaultFieldMapper : IFieldMapper
    {
        public void MapFields(FieldMappingContext context)
        {
            if (context == null || context.SourceObject == null || context.TargetObject == null)
                return;

            foreach (var mapping in context.FieldMappings)
            {
                try
                {
                    var sourceValue = GetFieldValue(context.SourceObject, mapping.Key);
                    SetFieldValue(context.TargetObject, mapping.Value, sourceValue);
                }
                catch (Exception ex)
                {
                    UniversalWorkflowFrameworkDiagnosticContext.Record(DiagnosticEvents.FieldMap.Error, new { message = ex.Message, error = ex.Message });
                }
            }
        }

        private object GetFieldValue(object obj, string fieldName)
        {
            var property = obj.GetType().GetProperty(fieldName, BindingFlags.Public | BindingFlags.Instance);
            if (property != null && property.CanRead)
            {
                return property.GetValue(obj);
            }

            var field = obj.GetType().GetField(fieldName, BindingFlags.Public | BindingFlags.Instance);
            if (field != null)
            {
                return field.GetValue(obj);
            }

            return null;
        }

        private void SetFieldValue(object obj, string fieldName, object value)
        {
            var property = obj.GetType().GetProperty(fieldName, BindingFlags.Public | BindingFlags.Instance);
            if (property != null && property.CanWrite)
            {
                property.SetValue(obj, value);
                return;
            }

            var field = obj.GetType().GetField(fieldName, BindingFlags.Public | BindingFlags.Instance);
            if (field != null)
            {
                field.SetValue(obj, value);
            }
        }
    }

